string f="Assets/Maps/Buildings/Textures/WeatheredAsphalt_DoubleLine_01";UnityEditor.AssetDatabase.Refresh();var sh=UnityEditor.AssetDatabase.LoadAssetAtPath<Shader>(f+"/AsphaltDoubleLine90.shader");var src=UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(f+"/M_Asphalt_DoubleLine_URP.mat");string p=f+"/M_Asphalt_DoubleLine_90_URP.mat";if(System.IO.File.Exists(p))throw new Exception("Refuse overwrite");var m=new Material(src);m.name="M_Asphalt_DoubleLine_90_URP";m.shader=sh;UnityEditor.AssetDatabase.CreateAsset(m,p);return new{material=p,errors=UnityEditor.ShaderUtil.ShaderHasError(sh),messages=UnityEditor.ShaderUtil.GetShaderMessages(sh).Select(v=>v.message).ToArray()};
